const { FaceDetector } = await import('/vendor/mediapipe/vision_bundle.mjs');
const FILES = { wasmLoaderPath: '/vendor/mediapipe/wasm/vision_wasm_internal.js', wasmBinaryPath: '/vendor/mediapipe/wasm/vision_wasm_internal.wasm' };
const det = await FaceDetector.createFromOptions(FILES, { baseOptions: { modelAssetPath: '/vendor/mediapipe/blaze_face_full_range.tflite', delegate: 'CPU' }, runningMode: 'IMAGE', minDetectionConfidence: 0.35 });
const imgs = [...document.querySelectorAll('#lib-grid img, #lib-info img')];
await Promise.all(imgs.map((i) => (i.complete && i.naturalWidth) ? 1 : new Promise((r) => { i.addEventListener('load', r, { once: true }); setTimeout(r, 6000); })));
const log = [];
for (const im of imgs) {
  if (!im.naturalWidth) continue;
  const W = im.naturalWidth, H = im.naturalHeight;
  const c = document.createElement('canvas'); c.width = W; c.height = H;
  const g = c.getContext('2d'); g.drawImage(im, 0, 0);
  const orig = document.createElement('canvas'); orig.width = W; orig.height = H; orig.getContext('2d').drawImage(im, 0, 0);
  const boxes = [];
  const add = (x, y, w, h) => {
    for (const b of boxes) {
      const ix = Math.max(0, Math.min(b.x + b.w, x + w) - Math.max(b.x, x)), iy = Math.max(0, Math.min(b.y + b.h, y + h) - Math.max(b.y, y));
      if (ix * iy > 0.3 * Math.min(b.w * b.h, w * h)) return;
    }
    boxes.push({ x, y, w, h });
  };
  for (const d of det.detect(orig).detections) { const b = d.boundingBox; add(b.originX, b.originY, b.width, b.height); }
  // small heads of the body views: strips of the top part, enlarged
  const S = 4, sw = Math.round(W / 6), sh = Math.round(H * 0.4);
  const up = document.createElement('canvas'); up.width = sw * S; up.height = sh * S;
  const ug = up.getContext('2d');
  for (let sx = 0; sx + sw <= W + 1; sx += Math.round(sw / 2)) {
    ug.clearRect(0, 0, up.width, up.height);
    ug.drawImage(orig, sx, 0, sw, sh, 0, 0, up.width, up.height);
    for (const d of det.detect(up).detections) { const b = d.boundingBox; add(sx + b.originX / S, b.originY / S, b.width / S, b.height / S); }
  }
  // the body views: the band of their heads blurred across, so a profile or the back of a head goes too
  const big = boxes.filter((b) => b.h >= 0.25 * H).sort((p, q) => q.w * q.h - p.w * p.h)[0];
  const small = boxes.filter((b) => b.h < 0.25 * H && (!big || b.x > big.x + big.w));
  if (small.length) {
    const hh = Math.max(...small.map((b) => b.h));
    const y0 = Math.max(0, Math.min(...small.map((b) => b.y)) - hh * 0.7), y1 = Math.min(H, Math.max(...small.map((b) => b.y + b.h)) + hh * 0.35);
    const x0 = big ? Math.min(W, big.x + big.w * 1.4) : Math.min(...small.map((b) => b.x)) - hh;
    g.save(); g.beginPath(); g.rect(x0, y0, W - x0, y1 - y0); g.clip();
    g.filter = 'blur(' + Math.max(3, Math.round(hh * 0.25)) + 'px)'; g.drawImage(orig, 0, 0); g.drawImage(orig, 0, 0); g.restore();
  }
  for (const b of boxes) {
    const x = b.x - b.w * 0.35, y = b.y - b.h * 0.55, w = b.w * 1.7, h = b.h * 1.85;
    g.save(); g.beginPath(); g.ellipse(x + w / 2, y + h / 2, w / 2, h / 2, 0, 0, Math.PI * 2); g.clip();
    g.filter = 'blur(' + Math.max(4, Math.round(w * 0.14)) + 'px)';
    g.drawImage(orig, 0, 0); g.drawImage(orig, 0, 0);
    g.restore();
  }
  log.push(boxes.length);
  im.removeAttribute('srcset');
  im.src = c.toDataURL('image/jpeg', 0.92);
}
det.close();
document.body.dataset.blurred = log.join(',');
